textarea[data-state="over"] {
  border-color: red;
}

textarea[data-state="warning"] {
  border-color: orange;
}

/* Tailwind */
.counter {
  @apply text-gray-500 data-[state=over]:text-red-500 data-[state=warning]:text-amber-500;
}
